static char *slot[NSLOTS];
static unsigned int slotn[NSLOTS];
static unsigned char slott[NSLOTS];

static int intact(int s)
{
    unsigned int i;
    for (i = 0; i < slotn[s]; i++)
        if ((unsigned char)slot[s][i] != slott[s])
            return 0;
    return 1;
}

int main(void)
{
    size_t k, nops = sizeof ops / sizeof ops[0];
    int corrupt = 0, nullbad = 0, s;
    for (k = 0; k < nops; k++) {
        unsigned int a = ops[k][1], b = ops[k][2];
        switch (ops[k][0]) {
        case 0:
            slot[a] = my_malloc(b);
            if (!slot[a]) { nullbad++; slotn[a] = 0; break; }
            slotn[a] = b;
            slott[a] = (unsigned char)(k * 131u + 7u);
            memset(slot[a], slott[a], b);
            break;
        case 1:
            if (slot[a] && !intact((int)a))
                corrupt++;
            my_free(slot[a]);
            slot[a] = NULL;
            break;
        case 2:
            my_set_policy((int)a);
            break;
        case 3:
            my_heap_dump();
            break;
        case 4:
            if (my_malloc(b ? (size_t)1073741825 : (size_t)0) != NULL)
                nullbad++;
            break;
        case 5:
            my_free(NULL);
            break;
        }
    }
    for (s = 0; s < NSLOTS; s++)
        if (slot[s] && !intact(s))
            corrupt++;
    printf("corrupt %d nullbad %d\n", corrupt, nullbad);
    return 0;
}
